import * as THREE from 'three/webgpu';
import { uv, texture, color, mix, sin, abs, mul, add } from 'three/tsl';
import { createText } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Scene placement
  const sp = config.scenePosition || { position: [0, 1, 0.06], rotation: [0, 0, 0], scale: [1, 1, 1] };
  group.position.set(...sp.position);
  group.rotation.set(...sp.rotation);
  group.scale.set(...sp.scale);

  // Load brushed metal texture
  const brushedTexture = ctx.textureLoader.load('/prism-assets/chrome/brushed-metal.map.png');

  // Plane geometry (size 1x1 to respect scale)
  const planeGeo = new THREE.PlaneGeometry(1, 1);

  // --- Engineered Gradient + Subtle Grain (TSL nodes) ---
  const u = uv().x;
  const v = uv().y;

  // Horizontal gradient: ink (left) → paper (right)
  const gradientColor = mix(
    color('#16161d'),
    color('#e8ecf2'),
    u
  );

  // Subtle grain noise (based on UV)
  const grain = sin(mul(uv(), 100.0)).abs().mul(0.05);

  // Brushed metal node
  const brushedNode = texture(brushedTexture);

  // Combine: brushed metal * gradient + grain
  const finalColor = add(mul(brushedNode, gradientColor), grain);

  const material = new THREE.MeshBasicNodeMaterial({
    colorNode: finalColor,
  });

  const plane = new THREE.Mesh(planeGeo, material);
  group.add(plane);

  // --- Text: "Collection 2" (headline, 0.34 scene units) ---
  const textMesh = createText({
    text: 'Collection 2',
    fontFamily: 'Lora',
    fontWeight: 400,
    fontSize: 0.34,         // headline height from type scale
    fontAtlas: ctx.fontAtlas,
  });

  // Slightly in front of the plane
  textMesh.position.set(0, 0, 0.001);
  group.add(textMesh);

  // Cleanup
  group.userData.cleanup = () => {
    planeGeo.dispose();
    material.dispose();
    brushedTexture.dispose();

    if (textMesh.isMesh) {
      textMesh.geometry.dispose();
      if (Array.isArray(textMesh.material)) {
        textMesh.material.forEach(m => m.dispose());
      } else {
        textMesh.material.dispose();
      }
    }
    // No GSAP timelines to kill
  };

  // No event handlers needed
  group.userData.handlers = {};

  return group;
}
